import React from 'react';
import { NavLink } from 'react-router-dom';
import { Button, Alert } from 'react-bootstrap';

const Login = ({ history }) => {
  const [credenciales, setCredenciales] = React.useState({ username: '', password: '' });
  const [error, setError] = React.useState('');

  const handleLogin = async () => {
    // Simular login - en producción haría fetch al backend
    localStorage.setItem('jwtToken', 'simulated-token');
    localStorage.setItem('userRole', 'adminpro');
    history.push('/');
  };

  return (
    <div style={{ maxWidth: '350px', margin: '50px auto' }}>
      <h3>Iniciar Sesión</h3>
      {error && <Alert variant="danger">{error}</Alert>}
      <form onSubmit={handleLogin}>
        <div className="form-group">
          <label>Usuario</label>
          <input 
            type="text" 
            name="username" 
            value={credenciales.username} 
            onChange={e => setCredenciales({ ...credenciales, username: e.target.value })} 
            required 
          />
        </div>
        <div className="form-group">
          <label>Contraseña</label>
          <input 
            type="password" 
            name="password" 
            value={credenciales.password} 
            onChange={e => setCredenciales({ ...credenciales, password: e.target.value })} 
            required 
          />
        </div>
        <Button type="submit">Entrar</Button>
      </form>
    </div>
  );
};

export default Login;